frappe.ui.form.on('Sales Invoice', {
    refresh(frm) {
        // Show FBR status indicator
        if (frm.doc.custom_fbr_status) {
            const status = frm.doc.custom_fbr_status;
            const indicator = status === 'Valid' ? 'green' : status === 'Invalid' ? 'red' : 'orange';
            frm.dashboard.add_indicator(__('FBR Status: {0}', [status]), indicator);
        }

        if (frm.doc.docstatus === 0) {
            frm.add_custom_button(__('Post to FBR'), async () => {
                await post_single_invoice_to_fbr(frm);
            });
        }
        
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Post to FBR'), async () => {
                await post_single_invoice_to_fbr(frm);
            });
        }
        
        if (frm.doc.docstatus === 0) {
            frm.add_custom_button(__('Show FBR Payload'), async () => {
                try {
                    const r = await frappe.call({
                        method: 'fbr_e_invoicing.api.build_fbr_payload.build_fbr_payload',
                        args: { sales_invoice_name: frm.doc.name },
                        freeze: true,
                        freeze_message: __('Building payload...')
                    });

                    if (r && r.message) {
                        const json = JSON.stringify(r.message, null, 2);
                        const d = new frappe.ui.Dialog({
                            title: __('FBR Payload'),
                            size: 'large',
                            fields: [
                                {
                                    fieldtype: 'Code',
                                    fieldname: 'payload',
                                    options: 'JSON',
                                    read_only: 1,
                                    label: __('Payload'),
                                    height: 420
                                }
                            ],
                            primary_action_label: __('Copy to Clipboard'),
                            primary_action: () => {
                                const val = d.get_value('payload');
                                frappe.utils.copy_to_clipboard(val);
                                frappe.show_alert({ message: __('Copied!'), indicator: 'green' });
                            }
                        });
                        d.set_value('payload', json);
                        d.show();
                    }
                } catch (err) {
                    frappe.msgprint({
                        title: __('Error'),
                        indicator: 'red',
                        message: __(err?.message || 'Failed to build payload')
                    });
                }
            });
        }
    },

    customer(frm) {
        if (frm.doc.customer) {
            frappe.db.get_value('Customer', frm.doc.customer, 'custom_province')
                .then(r => {
                    const province = r?.message?.custom_province;
                    if (province) {
                        frm.set_value('custom_province', province);
                    }
                });
        }
    },

    posting_date(frm) {
        if (frm.doc.posting_date && frm.doc.custom_submit_to_fbr) {
            const today = frappe.datetime.get_today();
            if (frm.doc.posting_date !== today) {
                frappe.msgprint({
                    title: __('FBR Validation'),
                    indicator: 'orange',
                    message: __('For FBR submission, posting date should be current date ({0})', [today])
                });
            }
        }
    }
});

// Function to handle single invoice FBR posting
async function post_single_invoice_to_fbr(frm, is_retry = false) {
    // Validate posting date
    const today = frappe.datetime.get_today();
    if (frm.doc.posting_date !== today) {
        frappe.confirm(
            __('Posting date is not current date. FBR requires current date for submission. Continue anyway?'),
            () => proceed_with_fbr_posting(),
            () => frappe.msgprint(__('FBR submission cancelled'))
        );
        return;
    }
    
    await proceed_with_fbr_posting();

    async function proceed_with_fbr_posting() {
        // console.log("Inside posting");
        try {
            // Update queue status
            // frm.set_value('custom_fbr_queue_status', 'Processing');
            // await frm.save();

            const r = await frappe.call({
                method: 'fbr_e_invoicing.api.fbr_submission.submit_single_invoice',
                args: { 
                    doctype: 'Sales Invoice',
                    docname: frm.doc.name,
                    is_retry: is_retry 
                },
                freeze: true,
                freeze_message: __('Posting invoice to FBR...')
            });

            const response = r && r.message;
            if (response) {
                // Save values in custom fields
                frm.set_value('custom_fbr_response', JSON.stringify(response, null, 2));
                frm.set_value('custom_fbr_invoice_number', response.invoiceNumber || '');
                frm.set_value('custom_fbr_datetime', response.dated || '');
                frm.set_value('custom_fbr_status', (response.validationResponse && response.validationResponse.status) || '');
                // frm.set_value('custom_fbr_queue_status', 'Completed');

                const status = response.validationResponse?.status;
                const indicator = status === 'Valid' ? 'green' : 'orange';
                
                frappe.show_alert({ 
                    message: __('FBR response saved. Status: {0}', [status]), 
                    indicator: indicator 
                });
                
                await frm.save();
            }
        } catch (err) {
            
            frappe.msgprint({
                title: __('Error'),
                indicator: 'red',
                message: __(err?.message || 'Failed to post invoice to FBR')
            });
            
            await frm.save();
        }
    }
}

frappe.ui.form.on('POS Invoice', {
    refresh(frm) {
        // Show FBR status indicator
        if (frm.doc.custom_fbr_status) {
            const status = frm.doc.custom_fbr_status;
            const indicator = status === 'Valid' ? 'green' : status === 'Invalid' ? 'red' : 'orange';
            frm.dashboard.add_indicator(__('FBR Status: {0}', [status]), indicator);
        }

        if (frm.doc.docstatus === 0) {
            // Manual Post to FBR
            frm.add_custom_button(__('Post to FBR'), async () => {
                await post_pos_invoice_to_fbr(frm);
            });
        }

        if (frm.doc.docstatus === 1) {
            // Show FBR Payload
            frm.add_custom_button(__('Show FBR Payload'), async () => {
                await show_fbr_payload_dialog(frm);
            });

            // Retry FBR Submission (if failed)
            if (frm.doc.custom_fbr_status === 'Invalid' || frm.doc.custom_fbr_status === 'Error' || !frm.doc.custom_fbr_status) {
                frm.add_custom_button(__('Retry FBR'), async () => {
                    await post_pos_invoice_to_fbr(frm, true);
                });
            }
        }
    },

    // Auto-submit to FBR on save if checkbox is checked
    after_save(frm) {
        if (frm.doc.custom_submit_to_fbr && frm.doc.docstatus === 1 && !frm.doc.custom_fbr_invoice_number) {
            // Auto-submit to FBR after successful save
            setTimeout(() => {
                post_pos_invoice_to_fbr(frm, false, true);
            }, 1000);
        }
    },

    // Validate before submit
    validate(frm) {
        if (frm.doc.custom_submit_to_fbr) {
            // Check if required FBR fields are present
            if (!frm.doc.custom_province) {
                frappe.validated = false;
                frappe.msgprint(__('Buyer Province is required for FBR submission'));
                return;
            }

            // Check if items have HS codes and Sale Types
            const missing_hs_codes = [];
            const missing_sale_types = [];

            frm.doc.items?.forEach((item, idx) => {
                if (!item.custom_hs_code) {
                    missing_hs_codes.push(`Row ${idx + 1}: ${item.item_name}`);
                }
                if (!item.custom_sale_type) {
                    missing_sale_types.push(`Row ${idx + 1}: ${item.item_name}`);
                }
            });

            if (missing_hs_codes.length > 0) {
                frappe.validated = false;
                frappe.msgprint({
                    title: __('Missing HS Codes'),
                    message: __('The following items are missing HS Codes required for FBR:<br>{0}', [missing_hs_codes.join('<br>')]),
                    indicator: 'red'
                });
                return;
            }

            if (missing_sale_types.length > 0) {
                frappe.validated = false;
                frappe.msgprint({
                    title: __('Missing Sale Types'),
                    message: __('The following items are missing Sale Type required for FBR:<br>{0}', [missing_sale_types.join('<br>')]),
                    indicator: 'red'
                });
                return;
            }
        }
    }
});

// Function to handle POS invoice FBR posting
async function post_pos_invoice_to_fbr(frm, is_retry = false, is_auto = false) {
    try {
        // Update queue status
        if (!is_auto) {

            await frm.save();
        }

        const r = await frappe.call({
            method: 'fbr_e_invoicing.api.fbr_submission.submit_single_invoice',
            args: {
                doctype: 'POS Invoice',
                docname: frm.doc.name,
                is_retry: is_retry
            },
            freeze: !is_auto,
            freeze_message: __('Posting invoice to FBR...')
        });

        const response = r && r.message;
        if (response) {
            // Save values in custom fields
            frm.set_value('custom_fbr_response', JSON.stringify(response, null, 2));
            frm.set_value('custom_fbr_invoice_number', response.invoiceNumber || '');
            frm.set_value('custom_fbr_datetime', response.dated || '');
            frm.set_value('custom_fbr_status', (response.validationResponse && response.validationResponse.status) || '');

            const status = response.validationResponse?.status;

            if (status === 'Valid') {

                if (!is_auto) {
                    frappe.show_alert({
                        message: __('FBR submission successful!'),
                        indicator: 'green'
                    });
                }
            } else {
                // Invalid response - add to queue for retry


                // Add to FBR Queue for retry
                frappe.call({
                    method: 'fbr_e_invoicing.api.fbr_queue.add_to_queue',
                    args: {
                        doctype: 'POS Invoice',
                        docname: frm.doc.name,
                        status: status,
                        error_message: response.validationResponse?.error || 'Invalid response from FBR'
                    }
                });

                if (!is_auto) {
                    frappe.show_alert({
                        message: __('FBR submission invalid. Added to retry queue.'),
                        indicator: 'orange'
                    });
                } else {
                    // For auto submissions, show a less intrusive message
                    frappe.show_alert({
                        message: __('Invoice saved. FBR submission queued for retry.'),
                        indicator: 'orange'
                    });
                }
            }

            await frm.save();
        }
    } catch (err) {
        // Update queue status and error



        // Add to FBR Queue for retry
        frappe.call({
            method: 'fbr_e_invoicing.api.fbr_queue.add_to_queue',
            args: {
                doctype: 'POS Invoice',
                docname: frm.doc.name,
                status: 'Error',
                error_message: err?.message || 'Unknown error'
            }
        });

        if (!is_auto) {
            frappe.msgprint({
                title: __('Error'),
                indicator: 'red',
                message: __(err?.message || 'Failed to post invoice to FBR. Added to retry queue.')
            });
        } else {
            frappe.show_alert({
                message: __('Invoice saved. FBR submission failed - added to retry queue.'),
                indicator: 'orange'
            });
        }

        await frm.save();
    }
}

// Function to show FBR payload dialog
async function show_fbr_payload_dialog(frm) {
    try {
        const r = await frappe.call({
            method: 'fbr_e_invoicing.api.build_fbr_payload.build_pos_fbr_payload',
            args: { pos_invoice_name: frm.doc.name },
            freeze: true,
            freeze_message: __('Building payload...')
        });

        if (r && r.message) {
            const json = JSON.stringify(r.message, null, 2);
            const d = new frappe.ui.Dialog({
                title: __('FBR Payload'),
                size: 'large',
                fields: [
                    {
                        fieldtype: 'Code',
                        fieldname: 'payload',
                        options: 'JSON',
                        read_only: 1,
                        label: __('Payload'),
                        height: 420
                    }
                ],
                primary_action_label: __('Copy to Clipboard'),
                primary_action: () => {
                    const val = d.get_value('payload');
                    frappe.utils.copy_to_clipboard(val);
                    frappe.show_alert({ message: __('Copied!'), indicator: 'green' });
                }
            });
            d.set_value('payload', json);
            d.show();
        }
    } catch (err) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __(err?.message || 'Failed to build payload')
        });
    }
}
